package com.gomgomapps.math.core;
import java.math.*;import java.util.*;import org.junit.Test;import static org.junit.Assert.*;
public class FractionDecimalPercentRecallTest {
 private static Question q(String n,String d){return new Question(FractionDecimalPercentRecall.ID,FractionDecimalPercentRecall.prompt(n,d),"poison","999","999");}
 private static Checker.Result check(Question q,String decimal,String percent){return new Checker().check(q,List.of(),Arrays.asList(decimal,percent));}
 @Test public void exactDecimalAndNumericPercentRecallAllowFamiliarFiniteAndGeneralRecurringValues(){
  String[][] rows={{"3","4","0.75","75"},{"1","5","0.2","20"},{"2","5","0.4","40"},{"3","5","0.6","60"},{"4","5","0.8","80"},{"1","3","0.(3)","33.(3)"},{"4","3","1.(3)","133.3(3)"},{"3","2","1.5","150"},{"0","7","0","0"},{"1","1","1","100"}};
  for(String[] row:rows){Question q=q(row[0],row[1]);assertNotNull(FractionDecimalPercentRecall.read(q));assertTrue(Arrays.toString(row),check(q,row[2],row[3]).correct());assertTrue(CurriculumLimits.NONE.allows(q));assertEquals(4,HelpPlan.forQuestion(q).size());}
  Question third=q("1","3");assertTrue(check(third,"0.3(3)","33.(33)").correct());assertEquals(Checker.Status.WRONG_ANSWER,check(third,"0.333","33.(3)").status);assertEquals(Checker.Status.WRONG_ANSWER,check(third,"0.(3)","33.333").status);Question raw=q("006","012");assertEquals("006",FractionDecimalPercentRecall.read(raw).rawNumerator());assertEquals("012",FractionDecimalPercentRecall.read(raw).rawDenominator());assertEquals(Rational.of(1,2),FractionDecimalPercentRecall.read(raw).value());assertTrue(check(raw,"00.5000","050.00").correct());
 }
 @Test public void EachBodyErrorIsOwnedByItsActualScalarFieldAndPercentUnitIsAlreadyInTheLabel(){
  Question q=q("1","2");Checker.Result first=check(q,"0.4","50"),second=check(q,"0.5","40"),badFirst=check(q,"1/2","50"),badSecond=check(q,"0.5","50%");assertEquals(Checker.Status.WRONG_ANSWER,first.status);assertEquals(0,first.index);assertEquals(Checker.Status.WRONG_ANSWER,second.status);assertEquals(1,second.index);assertEquals(Checker.Status.INPUT_NEEDED,badFirst.status);assertEquals(0,badFirst.index);assertEquals(Checker.Status.INPUT_NEEDED,badSecond.status);assertEquals(1,badSecond.index);for(Checker.Result r:List.of(first,second,badFirst,badSecond))assertEquals(Checker.InputTarget.ANSWER,r.inputTarget);assertEquals(0,check(q,null,"50").index);assertEquals(1,check(q,"0.5",null).index);assertTrue(check(q,"+0.50","+50.0").correct());assertTrue(check(q("1","1"),"0.(9)","99.(9)").correct());
 }
 @Test public void FourReadOnlyBlankFramesAndDraftVersionIgnoreStoredAnswersExpressionGuideAndWork(){
  Question q=q("1","3");q.studyGuide=new StudyGuide().step("private","private","","999");StudyGuide stored=q.studyGuide;StudyGuide guide=FractionDecimalPercentRecall.guide(q);HelpPlan h=HelpPlan.forQuestion(q);assertEquals(4,h.size());assertFalse(h.canTransfer());assertEquals(FractionDecimalPercentRecall.VERSION,guide.teachingVersion);assertEquals("1/3",guide.frames.get(2).expected);assertEquals("100/3",guide.frames.get(3).expected);List<String> entries=List.of("1.0","3","0.(3)","33.(3)");for(int i=0;i<4;i++){assertTrue(h.step(i).accepts(entries.get(i)));assertFalse(h.step(i).accepts(""));assertEquals("",h.step(i).after);assertEquals(FractionDecimalPercentRecall.ID,guide.frames.get(i).inputFormat);}assertFalse(h.step(2).accepts("1/3"));assertFalse(h.step(3).accepts("33.333"));assertFalse(h.step(3).accepts("33.(3)%"));HelpPlan.Draft draft=h.restore(null,q.id);assertEquals(List.of(""),draft.entries);assertEquals(FractionDecimalPercentRecall.VERSION,draft.teachingVersion);draft.entries=new ArrayList<>(entries);draft.stage=4;assertEquals(4,h.restore(draft.copy(),q.id).stage);assertEquals("33.(3)",h.enteredAnswer(draft));assertSame(stored,q.studyGuide);assertEquals("poison",q.expression);assertArrayEquals(new String[]{"999","999"},q.answers);
  q.expression=null;q.answers=null;q.stepSupport=true;q.calculationMethod="written";assertTrue(new Checker().check(q,List.of("999=999"),List.of("0.(3)","33.(3)"),List.of(Checker.StepKind.FULL)).correct());assertEquals(4,HelpPlan.forQuestion(q).size());assertSame(stored,q.studyGuide);assertNull(q.expression);assertNull(q.answers);
 }
 @Test public void ReferencesOnlyReuseCheckedLearnerOriginalsAndDecimalWithoutPercentPrefill(){
  Question q=q("006","012");assertEquals(Map.of("분자 n = ","006"),FractionDecimalPercentRecall.references(q,2,List.of("006","999")));assertEquals(Map.of("분자 n = ","006","분모 d = ","012","소수 v = ","0.5000"),FractionDecimalPercentRecall.references(q,3,List.of("006","012","0.5000")));assertEquals(Map.of(),FractionDecimalPercentRecall.references(q,3,List.of("999","999","0.4")));assertEquals(Map.of(),FractionDecimalPercentRecall.references(q,4,List.of("006","012","0.5000","50")));assertEquals(Map.of(),FractionDecimalPercentRecall.references(q,1,List.of("006")));assertEquals(Map.of(),FractionDecimalPercentRecall.references(q,3,null));assertEquals(Map.of(),FractionDecimalPercentRecall.references(null,3,List.of()));
 }
 @Test public void LargeOriginalsAndTwentyTwoDigitPercentageTargetsRemainReachableWithoutPeriodExpansion(){
  String n="99999999999999999999",p="9999999999999999999900";Question q=q(n,"1");assertTrue(check(q,n,p).correct());HelpPlan h=HelpPlan.forQuestion(q);assertTrue(h.step(0).accepts(n));assertTrue(h.step(1).accepts("1"));assertTrue(h.step(2).accepts(n));assertTrue(h.step(3).accepts(p));assertEquals(p,FractionDecimalPercentRecall.guide(q).frames.get(3).expected);
  Question finite=q("1","73786976294838206464");var value=FractionDecimalPercentRecall.read(finite).value();String decimal=value.decimalText(),percent=value.mul(Rational.of(100)).decimalText();assertTrue(check(finite,decimal,percent).correct());assertTrue(HelpPlan.forQuestion(finite).step(2).accepts(decimal));assertTrue(HelpPlan.forQuestion(finite).step(3).accepts(percent));Question period=q("1","99999999999999999989");assertEquals(4,HelpPlan.forQuestion(period).size());assertEquals("1/99999999999999999989",FractionDecimalPercentRecall.guide(period).frames.get(2).expected);assertEquals("100/99999999999999999989",FractionDecimalPercentRecall.guide(period).frames.get(3).expected);
 }
 @Test public void InputAndPublicGrammarGuardsReturnNoStoredGuideFallbackAndDoNotWidenSharedParsers(){
  for(String raw:List.of("1/2","1e2","0,5","50%","0.5+0","0.5…",".5","0.()","1.","1".repeat(121),BigInteger.ONE.shiftLeft(512).toString()))assertNull(raw,FractionDecimalPercentRecall.numericInput(raw));assertNull(FractionDecimalPercentRecall.numericInput(null));assertEquals(Rational.ZERO,FractionDecimalPercentRecall.numericInput("0".repeat(120)));assertEquals(Rational.of(-1,2),FractionDecimalPercentRecall.numericInput("−0.5"));
  for(Question q:List.of(q("1","0"),q("-1","2"),q("1".repeat(21),"2"),q("1","1".repeat(21)),q("1e2","2"))){q.studyGuide=new StudyGuide().step("private","private","","999");StudyGuide stored=q.studyGuide;assertNull(FractionDecimalPercentRecall.read(q));assertNull(HelpPlan.forQuestion(q));assertSame(stored,q.studyGuide);assertEquals(Checker.Status.INPUT_NEEDED,check(q,"999","999").status);assertFalse(CurriculumLimits.NONE.allows(q));}assertNull(FractionDecimalPercentRecall.read(null));assertNull(FractionDecimalPercentRecall.guide(null));Question extra=q("1","2");extra.prompt+=" extra";assertNull(FractionDecimalPercentRecall.read(extra));assertFalse(FractionDecimalPercentRecall.supports(null));try{Expression.number("0."+"1".repeat(13));fail("Shared decimal guard widened");}catch(IllegalArgumentException expected){}assertEquals(Checker.Status.INPUT_NEEDED,new Checker().check(q("1","2"),List.of(),List.of("0.5")).status);
 }
}
